/// <summary>
/// Base class for PricingAttribute table <c>InventDim</c>.
/// </summary>
internal abstract class UPSPricingAttributeInventDim extends UPSAbstractPricingAttribute implements UPSIPricingAttribute
{
}

Method.Source:
protected InventDim getTableRecord(Common _pricingObject)
{
    SalesLine salesLine = _pricingObject as SalesLine;
    InventDim inventDim;

    if (salesLine)
    {
        inventDim = salesLine.inventDim();
    }

    return inventDim;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(SalesLine)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(SalesLine));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(SalesLine));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(SalesLine), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(InventDim));
        qbds.addLink(fieldNum(SalesLine, InventDimId), fieldNum(InventDim, inventDimId));
        qbds.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
